for p in d['links']:
 for nid,side in [(p['start'],1),(p['end'],2)]:incident.setdefault(nid,set()).add(rhos[p['id']].get('rho_'+str(side)))
for name in ['03_outputs/viewer_dataset.json','03_outputs/summary.json','03_outputs/response.json']:
 expected=next(x['sha256'] for x in manifest['files'] if x['path']==name)
 assert hashlib.sha256((src/name).read_bytes()).hexdigest()==expected
bounds=d['metadata']['bounds']; scale=min(820/(bounds['max_x']-bounds['min_x']),460/(bounds['max_y']-bounds['min_y']))
def xy(x,y):return {'x':round(450+(x-(bounds['max_x']+bounds['min_x'])/2)*scale,5),'y':round(270-(y-(bounds['max_y']+bounds['min_y'])/2)*scale,5)}
def mul(v,k):return v*k if isinstance(v,(float,int)) else None
kind={'开关阀':'valve','二通':'node','三通':'node','定压泵':'pump','增压泵':'pump','水厂':'plant','软表':'node','堵头':'cap','用户':'user'}
