byid={n['id']:n for n in nodes}; pipes=[]
for p in d['links']:
 a,b=byid[p['start']],byid[p['end']]
 pipes.append(dict(id=p['id'],name=p['name'],type='pipe',start=p['start'],end=p['end'],a={k:a[k] for k in ['x','y']},b={k:b[k] for k in ['x','y']},diameter=p['diameter_mm'],length=p['length_m'],material=p['material'],startElevation=a['elevation'],endElevation=b['elevation'],geometry=[xy(x,y) for x,y in p['geometry']]))
assert len(nodes)==5539 and len(pipes)==5603
fn={};fp={};ports={}
for n in d['nodes']:
 m=n['metrics'];densities=incident.get(n['id'],set());rho=next(iter(densities)) if len(densities)==1 else None;flow=mul(m['flow_m3s'],3600) if m['flow_m3s'] is not None else mul(m['flow_kg_s'],3600/rho) if rho else None;fn[n['id']]={'pressure':mul(m['pressure_gauge_kpa'],.001),'head':m['head_m'],'flow':flow,'age':None,'pressureMin':mul(m['pressure_min_kpa'],.001),'pressureMax':mul(m['pressure_max_kpa'],.001)}
 ports[n['id']]=[{'pipe':p['link_id'],'port':p['port'],'side':p['side'],'pressure':mul(p['metrics']['pressure_gauge_kpa'],.001),'head':p['metrics']['head_m']} for p in n['ports']]
for p in d['links']:
 m=p['metrics'];fp[p['id']]={'pressure':mul(m['pressure_gauge_kpa'],.001),'head':m['head_m'],'flow':mul(m['signed_flow_m3s'] if p['flow_direction_known'] else m['flow_m3s'],3600),'velocity':m['velocity_mps'],'loss':abs(m['head_start_m']-m['head_end_m']) if m['head_start_m'] is not None and m['head_end_m'] is not None else None,'age':None,'pressureStart':mul(m['pressure_start_gauge_kpa'],.001),'pressureEnd':mul(m['pressure_end_gauge_kpa'],.001),'directionKnown':p['flow_direction_known']}
# No arbitrary port averaging, water-age inference, CRS projection, or invented daily frames.
data={'id':'suizhou-12152-20260921','topologyId':'SZ-20260921','projectId':'PRJ-SUIZHOU','completedAt':summary['finished_at'],'snapshot':{'schema':'water-topology-v1','sampleRevision':'suizhou-20260921','sourceDataset':'suizhou-12152-20260921','nodes':nodes,'pipes':pipes,'zones':[]},'frame':{'hour':9,'nodes':fn,'pipes':fp},'ports':ports,'sourceBoundaries':response['sources'],'metadata':d['metadata'],'audit':d['audit'],'demand':summary['mass_balance']['input_sink_m_kg_s']*3.6,'provenance':{'bundle':src.name,'calculateId':'12152','requestSHA256':summary['hashes']['request_sha256'],'timeBasis':'计算完成时间；原始数据未提供业务采样时刻'}}
